const b=($json.body&&typeof $json.body==='object')?$json.body:$json;
if (b.event !== 'invitee.created') return [];
const p=b.payload||{};
const campaign=(p.tracking&&p.tracking.utm_campaign)||'';
const contact=String(p.name||p.email||'').replace(/'/g,"''");
const occurred=(p.scheduled_event&&p.scheduled_event.start_time)||new Date().toISOString();
return [{json:{campaign,contact,occurred_at:occurred}}];

