INSERT INTO engagement_events (account, source, event_type, campaign, contact, value, occurred_at)
SELECT COALESCE((SELECT a.account FROM actions a WHERE a.utm_campaign = '{{ $json.campaign }}' LIMIT 1), 'unknown'),
       'calendly', 'meeting_booked', '{{ $json.campaign }}', '{{ $json.contact }}', 1, '{{ $json.occurred_at }}'::timestamptz;
